import {test} from 'node:test';import assert from 'node:assert/strict';import {createAdvisors,pickupAvailable} from '../ranch-advisors.mjs';
const state=()=>({seconds:0,pens:[],stock:{water:100,feed:100},calendar:{hour:12}});
const worker=id=>({person:{id,age:30},body:{visible:true},phase:'to-source',position:{x:0,z:0}});
test('persistent stalls flag, movement resolves, removed workers are pruned',()=>{const a=createAdvisors(),s=state(),w=worker('a');a.update(s,[w]);s.seconds=12;assert.equal(a.update(s,[w])[0].id,'routes');w.position.x=1;s.seconds=14;assert.equal(a.update(s,[w]).length,0);s.seconds=16;a.update(s,[]);assert.equal(a.size,0);});
test('monitor storage stays bounded over long runs',()=>{const a=createAdvisors(),s=state();for(let i=0;i<10000;i++){s.seconds=i*2;const notices=a.update(s,[worker(String(i))]);assert.ok(notices.length<=5);assert.equal(a.size,1);}a.clear();assert.equal(a.size,0);});
test('animal care checks report actual deficits and clear after recovery',()=>{const a=createAdvisors(),s=state();s.pens=[{animals:[{thirst:.8,hunger:.2}]}];assert.ok(a.update(s,[worker('a')]).some(n=>n.id==='water'));s.pens[0].animals[0].thirst=.2;s.seconds=2;assert.equal(a.update(s,[worker('a')]).length,0);});
test('one pickup per resource until the collector leaves',()=>{const s={activeJobs:{1:{resource:'water',phase:'reserved'}}};assert.equal(pickupAvailable(s,'water'),false);assert.equal(pickupAvailable(s,'feed'),true);s.activeJobs[1].phase='carrying';assert.equal(pickupAvailable(s,'water'),true);});
import {createCareState,reserveJob} from '../ranch-life-state.mjs';
test('busy water pickup does not prevent another worker collecting feed',()=>{const s=createCareState([{id:'a',species:'goat',count:2},{id:'b',species:'horse',count:2}]);const first=reserveJob(s,'one',r=>pickupAvailable(s,r));const second=reserveJob(s,'two',r=>pickupAvailable(s,r));assert.equal(first.resource,'water');assert.equal(second.resource,'feed');assert.equal(reserveJob(s,'three',r=>pickupAvailable(s,r)),null);});
